-- seed: structural defaults for every new hotel (business units, master lists, expense heads, ID proof types, payroll lists, the two single-row website tables)
-- GENERATED by db/scripts/generate-hotel-seeds.ts from db/seeds/source/pallav-hotel-defaults.json (each list names its Pallav source there).
-- Do not edit by hand: change the generator or the source and add a NEW seed file; an applied seed file is immutable.
-- Only structure: no real people, phone numbers, e-mails, bank data or Hotel Pallav text. Idempotent: running it twice changes nothing.

-- business units: database/migrations/2026_09_18_100001_create_business_units_table.php (Hotel Pallav -> Hotel, Pallav Food -> Food; codes HP/PF -> HOTEL/FOOD)
ON CONFLICT (slug) DO NOTHING;

-- master lists (option sets)
ON CONFLICT (key) DO NOTHING;

-- the entries of those lists (the first of each list is its default)
SELECT s.id, v.label, v.label, v.is_default, v.sort_order
FROM (VALUES
  ('payment_mode', 'Cash', true, 1),
  ('payment_mode', 'Card', false, 2),
  ('payment_mode', 'Debit', false, 3),
  ('payment_mode', 'Bank Transfer', false, 4),
  ('payment_mode', 'Cheque', false, 5),
  ('payment_mode', 'UPI', false, 6),
  ('payment_mode', 'Complimentary', false, 7),
  ('hotel_plan', 'EP', true, 1),
  ('hotel_plan', 'CP', false, 2),
  ('hotel_plan', 'MAP', false, 3),
  ('hotel_plan', 'AP', false, 4),
  ('shift', 'Morning', true, 1),
  ('shift', 'Afternoon', false, 2),
  ('shift', 'Evening', false, 3),
  ('shift', 'Night', false, 4),
  ('company_contact_role', 'Managing Director', true, 1),
  ('company_contact_role', 'HR Head', false, 2),
  ('company_contact_role', 'Assistant HR', false, 3),
  ('company_contact_role', 'Accountant Head', false, 4),
  ('company_contact_role', 'Accountant Assistant', false, 5),
  ('company_contact_role', 'Other', false, 6)
) AS v (set_key, label, is_default, sort_order)
JOIN option_sets s ON s.key = v.set_key
ON CONFLICT (option_set_id, value) DO NOTHING;

-- expense categories for both businesses: 2026_09_21_100000_create_expense_catalog_and_lines.php: the expense heads of Master Data became the first categories of each business, with no items (nothing invented); heads from 2026_09_18_120001_create_option_sets_table.php
ON CONFLICT (business, name) DO NOTHING;

-- ID proof types: database/seeders/DatabaseSeeder.php (IdProofType::updateOrCreate) and app/Support/PayrollMasters.php id_proofs defaults
ON CONFLICT (name) DO NOTHING;

-- payroll master lists shared by every company: app/Support/PayrollMasters.php LISTS defaults; separation_type from 2026_09_18_120001 (five exit types in the database, four in the code); salary_payment_mode from 2026_09_20_180000_make_salary_payment_modes_editable.php. Shared entries (no company).
ON CONFLICT (list, label) WHERE payroll_company_id IS NULL DO NOTHING;

-- the two fixed payroll companies, named after the hotel (hms.hotel_name is set by create-hotel): app/Models/PayrollCompany.php FIXED (FixedCompaniesTest): exactly two rows in this order, named after the hotel (the hotel name is passed to the seed run as @hotel_name by create-hotel and by `seed`); the CODES are business logic (HP01 pays the staff-meal charge, PF01 is the food provider) and are the same in every hotel
ON CONFLICT (code) DO NOTHING;

-- the settings the code reads (a hotel changes them on screen): MJ decision #19 (GST at check-out): the percent used at check-out is read from these two settings and stored with the stay and the bill (pms_stays and bill_master_bills hotel_gst_percent / food_gst_percent)
ON CONFLICT (key) DO NOTHING;

-- the single website rows (only the column defaults): Pallav creates these rows on first use (Site\Settings::current(), PageContent::current()); here they exist from the start, with only the column defaults
